/// `source`'s mark, `side` points square, in `color`.
pub(crate) fn image(source: Source, side: f64, color: &NSColor) -> Option<Retained<NSImage>> {
    crate::zed_logo::path_image(path(source), VIEW_BOX, NSWindingRule::NonZero, side, color, false)
}

fn path(source: Source) -> &'static str {
    match source {
        Source::Claude => CLAUDE,
        Source::Codex => OPENAI,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_marks_parse_inside_their_box() {
        for path in [CLAUDE, OPENAI] {
            assert!(crate::zed_logo::parses_inside(path, VIEW_BOX), "{}", path.chars().take(40).collect::<String>());
        }
    }
}
